const businessRow = $('Get Active Businesses with GBP').item.json;
const response = items[0].json;
const reviews = response.reviews || [];

return reviews.map(r => {
  const starMap = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
  return {
    json: {
      business_id: businessRow.business_id,
      business_name: businessRow.business_name,
      gbp_account_id: businessRow.gbp_account_id,
      location_id: businessRow.location_id,
      review_id: r.reviewId,
      reviewer_name: r.reviewer?.displayName || '',
      star_rating: r.starRating,
      star_number: starMap[r.starRating] || null,
      review_comment: r.comment || '',
      review_link: r.name ? `https://business.google.com/reviews/l/${businessRow.location_id || ''}` : null,
      create_time: r.createTime,
      has_existing_google_reply: !!r.reviewReply,
      existing_google_reply_comment: r.reviewReply?.comment || null
    }
  };
});

const reviews = $('Keep Review Data').all();
const checks = items;

return reviews.map((review, i) => ({
  json: {
    ...review.json,
    existing_activity_id: checks[i]?.json?.existing_activity_id || null,
    existing_status: checks[i]?.json?.existing_status || null
  }
}));

const review = $('New Review?').item.json;
const match = items[0].json;

return [{
  json: {
    ...review,
    customer_id: match.customer_id,
    matched_full_name: match.full_name,
    name_score: match.name_score
  }
}];

parameters.query:
insert into activities (
  business_id, customer_id, activity_type, review_received,
  activity_status, review_id, star_rating, star_number,
  review_comment, review_link, notes
) values (
  $1, $2, 'Follow-up', true, 'Pending', $3, $4, $5, $6, $7, $8
)
returning id;

